package net.officefloor.hq.app.settings;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.history.AsOfGuard;
import net.officefloor.hq.app.history.HistoryService;
import net.officefloor.hq.app.session.CurrentUser;
import net.officefloor.hq.app.sheet.DatedSetting;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class SettingsController {

    /** The sheet's settings as the screen shows them: the clerk limit with two decimals, null for
     *  none, the floor with two decimals, the terms in days, the late percent with two decimals,
     *  the policy date, null when blank, the period numbering from-date, null when blank (off),
     *  the terms each grade has of its own, a grade without them left out, the cap with two
     *  decimals, null for none, and the proof threshold with two decimals, null for none, the grace days, null when blank (off), the entry date, null when blank (off), each of the dated ones as in force on the sheet's today; and every
     *  value recorded for the dated settings, by key, each key's by from-date; and the permission
     *  matrix: the roles set for each action, comma separated, an action left blank left out. */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String cap, String proofThreshold,
            Integer graceDays, LocalDate entryDate, Map<String, List<DatedValue>> dated, Map<String, String> permissions) {
        static SettingsView of(BigDecimal clerkLimit, BigDecimal floor, int terms, BigDecimal latePct, LocalDate policyDate,
                LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, BigDecimal cap, BigDecimal proofThreshold,
                Integer graceDays, LocalDate entryDate, Map<String, List<DatedSetting>> dated, Map<Permission, String> permissions) {
            Map<String, String> perms = new TreeMap<>();
            permissions.forEach((action, roles) -> perms.put(action.key(), roles));
            return new SettingsView(clerkLimit == null ? null : clerkLimit.toPlainString(), floor.toPlainString(), terms,
                    latePct.setScale(2).toPlainString(), policyDate, periodNumberingFrom, gradeTerms,
                    cap == null ? null : cap.setScale(2).toPlainString(),
                    proofThreshold == null ? null : proofThreshold.setScale(2).toPlainString(), graceDays, entryDate, DatedValue.of(dated), perms);
        }
    }

    /** A value recorded for a dated setting: in force from its from-date until the next one of its
     *  key; null for none. */
    public record DatedValue(LocalDate from, String value) {
        /** Every value recorded, by key, each key's by from-date. */
        public static Map<String, List<DatedValue>> of(Map<String, List<DatedSetting>> dated) {
            Map<String, List<DatedValue>> out = new TreeMap<>();
            dated.forEach((key, values) -> out.put(key,
                    values.stream().map(d -> new DatedValue(d.getFrom(), d.getValue())).toList()));
            return out;
        }
    }

    /** A from-date as a form submits it: a date as yyyy-mm-dd, blank or left out for the sheet's today. */
    private static final String FROM = "(\\d{4}-\\d{2}-\\d{2})?";

    /** The clerk limit as the form submits it: 0.00 or more with up to two decimals, blank for no
     *  limit, from a date (blank: the sheet's today). */
    public record ClerkLimitForm(@NotNull @Pattern(regexp = "(\\d{1,13}(\\.\\d{1,2})?)?") String value,
            @Pattern(regexp = FROM) String from) {
    }

        return out;
    }

    @GetMapping("/roles")
    public List<RoleView> roles(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        List<SheetRole> roles = asOf == null ? service.roles(sheetId) : history.asOf(sheetId, asOf).roles();
        return roles.stream().map(RoleView::of).toList();
    }

    @PutMapping("/roles")
    public RoleView setRole(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RoleForm body) {
        return RoleView.of(service.setRole(sheetId, user.trim(), body.user().trim(), Role.of(body.role())));
    }

    @GetMapping("/delegations")
    public List<DelegationView> delegations(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.asOf(sheetId, asOf).delegations().entrySet().stream()
                    .map(e -> DelegationView.of(e.getKey(), e.getValue())).toList();
        }
        return service.delegations(sheetId).stream().map(DelegationView::of).toList();
    }

    @PostMapping("/delegations")
    public DelegationView delegate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody DelegationForm body) {
        return DelegationView.of(service.delegate(sheetId, user.trim(), body.user().trim(),
                fromOf(body.from()), fromOf(body.to())));
    }
}
     *  sheet created first if it was never loaded; a claim dated from then on to the next from-date
     *  whose due is above it cannot be opened while its note is empty. */
    @Transactional
    public BigDecimal setNoteThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
        Sheet sheet = sheets.load(sheetId, user);
        sheets.lock(sheetId);
        BigDecimal scaled = threshold == null ? null : threshold.setScale(2);
        record(sheet, user, NOTE_THRESHOLD, scaled == null ? "" : scaled.toPlainString(), from);
        return scaled;
    }

    /** Every value recorded for the sheet's dated settings, by key, each key's by from-date. */
    @Transactional(readOnly = true)
    public Map<String, List<DatedSetting>> datedSettings(String sheetId) {
        return sheets.find(sheetId).map(Sheet::getDatedSettings).orElse(Map.of());
    }

    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserAsc(sheetId);
    }

    /** The role a user name acts in on the sheet: a steward while a steward's delegation to it
     *  covers the sheet's today, else the role it holds. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        Role held = heldRoleOf(sheetId, user);
        return held != Role.STEWARD && delegatorOf(sheetId, user) != null ? Role.STEWARD : held;
    }

    /** The role a user name holds on the sheet in its own right: a clerk unless set otherwise. */
    @Transactional(readOnly = true)
    public Role heldRoleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** The steward whose delegation the user name acts under on the sheet's today; null when it
     *  acts in its own right (a steward itself, or no delegation covers the sheet's today). */
    @Transactional(readOnly = true)
    public String delegatorOf(String sheetId, String user) {
        List<SheetDelegation> made = delegations.findBySheetIdAndUserOrderByIdDesc(sheetId, user);
        if (made.isEmpty() || heldRoleOf(sheetId, user) == Role.STEWARD) {
            return null;
        }
        LocalDate today = sheets.today(sheetId);
        return made.stream().filter(d -> d.covers(today)).map(SheetDelegation::getSteward).findFirst().orElse(null);
    }

    @Transactional(readOnly = true)
    public List<SheetDelegation> delegations(String sheetId) {
        return delegations.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Delegate the steward role to a user name from a date (null: the sheet's today) to a date
     *  (null: the from-date), inclusive, the sheet created first if it was never loaded; refused
     *  (403) unless the user is a steward in its own right, and (400) for a to-date before the
     *  from-date. */
    @Transactional
    public SheetDelegation delegate(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        sheets.load(sheetId, user);
        if (heldRoleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may delegate");
        }
        LocalDate start = from == null ? sheets.today(sheetId) : from;
        LocalDate end = to == null ? start : to;
        if (end.isBefore(start)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date");
        }
        SheetDelegation made = delegations.saveAndFlush(new SheetDelegation(sheetId, name, user, start, end));
        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + name
                + " from=" + start + " to=" + end);
        return made;
    }

    /** Archive the sheet, the sheet created first if it was never loaded; refused (403) unless the
     *  user acts as a steward, and (409) when it is archived already. */
    @Transactional
    public Sheet archive(String sheetId, String user) {
        Sheet sheet = sheets.load(sheetId, user);
        sheets.lock(sheetId);
        if (roleOf(sheetId, user) != Role.STEWARD) {

